using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NewGameSetupTests
{
    static RegisteredOfficer Officer(string id="created:a",StartTemplate role=StartTemplate.Daimyo,string site="castle:a")=>new(id,null,"鏡山 宗久",1520,new(70,60,50,40),role,site,null,role==StartTemplate.Daimyo?"鏡山家":null);
    static SetupScenario Scenario(bool extra=true)=>new(1,"1560-01-01",
        [new("old:head","旧大名","castle:a","old:house",null,false,false),
         new("old:loyal","直属家臣","castle:a","old:house","old:head",false,true),
         new("old:child","陪臣","castle:a","old:house","old:loyal",false,true),
         new("old:local","城付き家臣","castle:a","old:house","old:head",false,false),
         new("guest","他家の客将","castle:a","guest:house",null,false,false)],
        extra?[new("castle:a","old:house"),new("castle:b","old:house"),new("castle:g","guest:house")]:[new("castle:a","old:house"),new("castle:g","guest:house")],
        [new("old:house","旧家","old:head","castle:a"),new("guest:house","客家","guest","castle:g")]);
    static WorldSetupRequest Request(bool all=false,bool absorb=false)=>new([Officer()],[new("created:a","created:house",all?["castle:a","castle:b"]:["castle:a"],absorb)]);
    static SetupPerson Person(SetupScenario s,string id)=>s.People.Single(p=>p.Id==id);
    static OfficerLibrary Library()=>new(1,[Officer(),Officer("created:b",StartTemplate.Ronin)],[new("group:a","尾張",[]),new("group:b","九州",[])]);
    [Fact]public void CopyAndEditDoesNotChangeSourceOrAnotherGroup(){var original=Library();string hash=ContractJson.CanonicalHash(original);var a=NewGameSetup.CopyToGroup(original,"created:a","group:a","created:copy-a");var b=NewGameSetup.CopyToGroup(a,"created:a","group:b","created:copy-b");b.Groups[0].Officers[0]=b.Groups[0].Officers[0] with{Name="別名",Attributes=new(1,2,3,4)};Assert.Equal(hash,ContractJson.CanonicalHash(original));Assert.Equal("鏡山 宗久",a.Groups[0].Officers[0].Name);Assert.Equal(70,b.Groups[1].Officers[0].Attributes.Leadership);Assert.Equal("created:a",b.Groups[0].Officers[0].CopiedFrom);}
    [Fact]public void IndividualMultiSelectionAndGroupCopiesAreIndependent(){var l=NewGameSetup.CopyToGroup(Library(),"created:a","group:a","created:copy");Assert.Equal(2,NewGameSetup.Select(l,["created:a","created:b"],null).Length);var selected=NewGameSetup.Select(l,[],"group:a");selected[0]=selected[0] with{Name="変更"};Assert.Equal("鏡山 宗久",l.Groups[0].Officers[0].Name);}
    [Fact]public void NoCreatedOfficersIsValid(){var s=Scenario();var p=NewGameSetup.Preview(s,new([],[]));Assert.True(p.IsEligible());Assert.Equal(ContractJson.CanonicalHash(s.People),ContractJson.CanonicalHash(p.World!.People));}
    [Fact]public void RemainingTerritoryMovesHeadAndPersonalFollowers(){var s=Scenario();string before=ContractJson.CanonicalHash(s);var p=NewGameSetup.Preview(s,Request());Assert.True(p.IsEligible(),string.Join(',',p.Errors));var w=p.World!;Assert.Equal("castle:b",Person(w,"old:head").Site);Assert.Equal("castle:b",Person(w,"old:loyal").Site);Assert.Equal("old:house",Person(w,"old:head").Faction);Assert.Equal("created:house",Person(w,"old:local").Faction);Assert.Equal("created:a",Person(w,"old:local").Lord);Assert.Equal(before,ContractJson.CanonicalHash(s));}
    [Fact]public void LossOfLastCastlePreservesPersonalRetinueAsRonin(){var p=NewGameSetup.Preview(Scenario(false),Request());Assert.True(p.IsEligible(),string.Join(',',p.Errors));var w=p.World!;foreach(var id in new[]{"old:head","old:loyal","old:child"})Assert.Null(Person(w,id).Faction);Assert.Equal("old:head",Person(w,"old:loyal").Lord);Assert.Equal("old:loyal",Person(w,"old:child").Lord);Assert.Equal("created:house",Person(w,"old:local").Faction);Assert.DoesNotContain(w.Factions,f=>f.Id=="old:house");}
    [Fact]public void ExplicitAbsorptionPreservesRetinueHierarchy(){var p=NewGameSetup.Preview(Scenario(false),Request(absorb:true));Assert.True(p.IsEligible());Assert.Equal("created:a",Person(p.World!,"old:head").Lord);Assert.Equal("old:head",Person(p.World!,"old:loyal").Lord);Assert.All(p.World!.People.Where(p=>p.Id.StartsWith("old:")),p=>Assert.Equal("created:house",p.Faction));}
    [Fact]public void AbsorptionDoesNotAffectHeadWithRemainingTerritory(){var p=NewGameSetup.Preview(Scenario(),Request(absorb:true));Assert.True(p.IsEligible());Assert.Null(Person(p.World!,"old:head").Lord);Assert.Equal("old:house",Person(p.World!,"old:head").Faction);}
    [Fact]public void ForeignGuestIsNotTransferred(){var s=Scenario();var p=NewGameSetup.Preview(s,Request());Assert.True(p.IsEligible());Assert.Equal(Person(s,"guest"),Person(p.World!,"guest"));}
    [Fact]public void DuplicateCastleClaimsAreRejectedWithoutChangingInputs(){var s=Scenario();var r=new WorldSetupRequest([Officer(),Officer("created:b")],[new("created:a","created:one",["castle:a"],false),new("created:b","created:two",["castle:a"],false)]);var bytes=ContractJson.Write(s);var p=NewGameSetup.Preview(s,r);Assert.False(p.IsEligible());Assert.Null(p.World);Assert.Empty(p.Changes);Assert.Equal(bytes,ContractJson.Write(s));}
    [Fact]public void SeveralCastlesCanBeAssignedToOneNewDaimyo(){var p=NewGameSetup.Preview(Scenario(),Request(all:true));Assert.True(p.IsEligible());Assert.Equal(2,p.World!.Castles.Count(c=>c.Faction=="created:house"));Assert.Null(Person(p.World!,"old:head").Faction);}
    [Fact]public void ScenarioDateControlsAgeAndCastleAffiliation(){var s=Scenario() with{EpochDate="1540-01-01"};var p=NewGameSetup.Preview(s,new([Officer(role:StartTemplate.Retainer)],[]));Assert.True(p.IsEligible());Assert.Equal("old:house",Person(p.World!,"created:a").Faction);Assert.False(NewGameSetup.Preview(s with{EpochDate="1510-01-01"},new([Officer(role:StartTemplate.Ronin)],[])).IsEligible());}
    [Fact]public void RetainerJoinsNewOwnerAfterSimultaneousPlacement(){var r=Request() with{Officers=[Officer(),Officer("created:b",StartTemplate.Retainer)]};var p=NewGameSetup.Preview(Scenario(),r);Assert.True(p.IsEligible());Assert.Equal("created:house",Person(p.World!,"created:b").Faction);Assert.Equal("created:a",Person(p.World!,"created:b").Lord);}
    [Fact]public void PreviewAndConfirmationRoundTripAreDeterministic(){var s=Scenario();var r=Request();var p=NewGameSetup.Preview(s,r);var restored=ContractJson.Read<WorldSetupPreview>(ContractJson.Write(p));Assert.Equal(ContractJson.Write(p),ContractJson.Write(restored));var w=NewGameSetup.Confirm(s,r,restored);Assert.Equal(ContractJson.CanonicalHash(p.World),ContractJson.CanonicalHash(w));w.People[0]=w.People[0] with{Name="変更"};Assert.NotEqual(ContractJson.CanonicalHash(w),ContractJson.CanonicalHash(p.World));}
    [Theory][InlineData("scenario")][InlineData("request")][InlineData("result")]
    public void ConfirmationRejectsChangesAfterReview(string kind){var s=Scenario();var r=Request();var p=NewGameSetup.Preview(s,r);if(kind=="scenario")s=s with{EpochDate="1561-01-01"};if(kind=="request")r=r with{Officers=[Officer() with{Name="変更"}]};if(kind=="result")p.World!.People[0]=p.World.People[0] with{Name="改ざん"};Assert.Throws<InvalidDataException>(()=>NewGameSetup.Confirm(s,r,p));}
    [Theory][InlineData("duplicate")][InlineData("missing")][InlineData("mixed")]
    public void InvalidSelectionIsRejected(string kind){Assert.Throws<InvalidDataException>(()=>NewGameSetup.Select(Library(),kind=="duplicate"?["created:a","created:a"]:kind=="missing"?["created:missing"]:["created:a"],kind=="mixed"?"group:a":null));}
    [Theory][InlineData("site")][InlineData("faction")][InlineData("home")][InlineData("cycle")][InlineData("negative")][InlineData("identity")]
    public void InvalidPlacementsAreRejected(string kind){var s=Scenario();var r=Request();if(kind=="site")r=r with{Officers=[Officer(site:"castle:missing")]};if(kind=="faction")r=r with{Daimyo=[r.Daimyo[0] with{Faction="old:house"}]};if(kind=="home")r=r with{Daimyo=[r.Daimyo[0] with{Castles=["castle:b"]}]};if(kind=="cycle")s.People[1]=s.People[1] with{Lord="old:child"};if(kind=="negative")r=r with{Officers=[Officer() with{Attributes=new(-1,2,3,4)}]};if(kind=="identity")r=r with{Officers=[Officer() with{Id="old:head"}]};Assert.False(NewGameSetup.Preview(s,r).IsEligible());}
    [Fact]public void OrderOfSelectionsDoesNotDetermineTerritoryWinner(){var s=Scenario();var a=Officer();var b=Officer("created:b",StartTemplate.Daimyo,"castle:g");var da=new DaimyoPlacement(a.Id,"created:one",["castle:a"],false);var db=new DaimyoPlacement(b.Id,"created:two",["castle:g"],false);var x=NewGameSetup.Preview(s,new([a,b],[da,db]));var y=NewGameSetup.Preview(s,new([b,a],[db,da]));Assert.True(x.IsEligible());Assert.True(y.IsEligible());Assert.Equal(ContractJson.CanonicalHash(x.World),ContractJson.CanonicalHash(y.World));}
}
